/*
# Seed Batch B: 4 draft surveys from surveys_spec.json

Inserts 4 surveys as drafts (status='draft') into guidance_surveys, linked to
indicators/programs/resources from the Zad reference tables. Idempotent via
ON CONFLICT (slug) DO NOTHING.

Surveys:
1. safe_ai — الاستخدام الآمن للذكاء الاصطناعي (16 items, 4 sections)
2. digital_ethics — آداب السلوك الرقمي (16 items, 5 sections)
3. conduct_knowledge — معرفة لائحة قواعد السلوك والمواظبة (15 items, 6 sections, publish_gate='pending')
4. achievement_factors — العوامل المؤثرة في التحصيل الدراسي (17 items, 5 sections)

No schema changes. No RLS changes. Data-only migration.
*/

INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('safe_ai', 'الاستخدام الآمن للذكاء الاصطناعي', 'student', 'draft', '{"type":"likert5","labels":["لا أوافق بشدة","لا أوافق","محايد","أوافق","أوافق بشدة"]}'::jsonb, 'نريد أن نعرف كيف يستخدم الطلاب أدوات الذكاء الاصطناعي لنرشدهم لاستخدام آمن ونزيه. إجاباتك لن تُستخدم لمحاسبتك.', '[{"id":"grade","text":"الصف","type":"single","options":["الأول الثانوي","الثاني الثانوي","الثالث الثانوي"]}]'::jsonb, '[{"id":"awareness","name":"الوعي بالمخاطر","swot_axis":"internal","items":[{"text":"أعرف أن أدوات الذكاء الاصطناعي قد تُخطئ أو تختلق معلومات.","reverse":false},{"text":"أعرف أن ما أكتبه للأداة قد يُخزَّن أو يُستخدم.","reverse":false},{"text":"أعرف المخاطر المرتبطة بالصور والمقاطع المصنوعة بالذكاء الاصطناعي (التزييف).","reverse":false},{"text":"أعرف أن لبعض الأدوات حدًّا أدنى للعمر وشروط استخدام.","reverse":false}],"if_low":["درس إرشادي: ماذا تعرف عن الذكاء الاصطناعي ومخاطره"]},{"id":"privacy","name":"حماية الخصوصية","swot_axis":"internal","items":[{"text":"لا أكتب بياناتي الشخصية (الاسم والهوية والعنوان) في أدوات الذكاء الاصطناعي.","reverse":false},{"text":"لا أرفع صورًا لي أو لغيري إلى أدوات غير موثوقة.","reverse":false},{"text":"أراجع إعدادات الخصوصية قبل استخدام أي أداة جديدة.","reverse":false},{"text":"لا أشارك كلمات مروري أو أرقام حساباتي مع أي أداة.","reverse":false}],"if_low":["برنامج الاستخدام الآمن للإنترنت: وحدة الخصوصية"]},{"id":"verify","name":"التحقق والتفكير النقدي","swot_axis":"internal","items":[{"text":"أتحقق من المعلومات التي تعطيها الأداة من مصدر آخر.","reverse":false},{"text":"أقارن إجابة الأداة بما تعلمته في الدرس.","reverse":false},{"text":"أعتبر إجابة الأداة صحيحة دائمًا دون مراجعتها.","reverse":true},{"text":"أستطيع التفريق بين ما يصلح وما لا يصلح الاعتماد فيه على الأداة.","reverse":false}],"if_low":["أنشطة تحقق من المصادر وتمييز المعلومات المضللة"]},{"id":"integrity","name":"النزاهة الأكاديمية","swot_axis":"internal","items":[{"text":"أعرف متى يُسمح لي باستخدام الأداة في الواجبات ومتى يُمنع.","reverse":false},{"text":"أذكر أنني استعنت بالأداة عندما يطلب المعلم ذلك.","reverse":false},{"text":"أسلّم أعمال الأداة على أنها عملي الشخصي.","reverse":true},{"text":"أستخدم الأداة لأفهم أكثر لا لأتجنب التفكير.","reverse":false}],"if_low":["توضيح سياسة المدرسة للنزاهة الأكاديمية واستخدام الأدوات","تنسيق مع المعلمين لتصميم مهام مقاومة للنسخ"]}]'::jsonb, '[{"id":"usage","text":"ما الأدوات التي تستخدمها؟ (اختيار متعدد)","type":"multi","options":["محادثات نصية","توليد صور","ترجمة وتلخيص","مساعد برمجة","لا أستخدم","أخرى"]},{"id":"purpose","text":"لأي غرض تستخدمها؟","type":"multi","options":["فهم الدروس","حل الواجبات","كتابة ملخصات","التسلية","البحث عن معلومة","أخرى"]},{"id":"freq","text":"عدد مرات الاستخدام الأسبوعية","type":"single","options":["لا أستخدم","1–2","3–5","أكثر من 5"]}]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['3-2-1-1','3-2-1-7']::text[], ARRAY['safe_net']::text[], ARRAY['p_safe_net']::text[], NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('digital_ethics', 'آداب السلوك الرقمي في المنصة الرقمية (مدرستي)', 'student', 'draft', '{"type":"likert5","labels":["أبدًا","نادرًا","أحيانًا","غالبًا","دائمًا"]}'::jsonb, 'يقيس هذا الاستبيان التزام الطلاب بآداب السلوك الرقمي في المنصة الدراسية (الدروس المباشرة والمنتديات والمهام).', '[{"id":"grade","text":"الصف","type":"single","options":["الأول الثانوي","الثاني الثانوي","الثالث الثانوي"]}]'::jsonb, '[{"id":"respect","name":"احترام التواصل","swot_axis":"internal","items":[{"text":"ألتزم بلغة محترمة في المحادثات والتعليقات.","reverse":false},{"text":"لا أكتب أو أرسل ما يسيء إلى أحد.","reverse":false},{"text":"لا أرسل رسائل أو صورًا خارج موضوع الدرس.","reverse":false},{"text":"أحترم دور الآخرين في الحديث أثناء الدرس المباشر.","reverse":false}],"if_low":["درس توعوي: آداب التواصل الرقمي مع أمثلة من المنصة"]},{"id":"integrity","name":"النزاهة الرقمية","swot_axis":"internal","items":[{"text":"أنجز المهام والاختبارات بنفسي دون مساعدة ممنوعة.","reverse":false},{"text":"لا أشارك إجابات الاختبار مع زملائي.","reverse":false},{"text":"لا أنسخ عمل زملائي وأنسبه لنفسي.","reverse":false}],"if_low":["التنسيق مع لجنة الاختبارات لتعزيز النزاهة"]},{"id":"privacy","name":"الخصوصية وحماية الحساب","swot_axis":"internal","items":[{"text":"لا أشارك اسم المستخدم وكلمة المرور مع أحد.","reverse":false},{"text":"لا أسجّل أو أصوّر الدروس أو الزملاء دون إذن.","reverse":false},{"text":"أخرج من حسابي بعد الانتهاء على الأجهزة المشتركة.","reverse":false}],"if_low":["حملة حماية الحسابات وعدم التصوير"]},{"id":"attendance","name":"الحضور والانضباط الافتراضي","swot_axis":"internal","items":[{"text":"أدخل الدرس المباشر في وقته.","reverse":false},{"text":"أفعّل الكاميرا/الميكروفون وفق تعليمات المعلم.","reverse":false},{"text":"أستخدم المنصة لأغراض الدراسة فقط خلال الحصة.","reverse":false}],"if_low":["رفع الانضباط بالتعاون مع وكيل شؤون الطلاب"]},{"id":"report","name":"الإبلاغ والمسؤولية","swot_axis":"internal","items":[{"text":"أبلغ المعلم أو الموجه عند رؤية إساءة رقمية.","reverse":false},{"text":"أعرف قناة الإبلاغ الرسمية للمدرسة عن الإساءة الرقمية.","reverse":false}],"if_low":["إعلان قناة الإبلاغ وتعريف الطلاب بها"]}]'::jsonb, '[]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['1-2-1-1','1-2-1-3','1-5-1-1','3-2-1-1','3-2-1-5','3-2-1-7']::text[], ARRAY['safe_net','conduct']::text[], ARRAY['p_safe_net','g_conduct']::text[], NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('conduct_knowledge', 'معرفة الطلبة المستجدين بلائحة قواعد السلوك والمواظبة', 'student', 'draft', '{"type":"true_false_dk","labels":["صحيح","خطأ","لا أعلم"]}'::jsonb, 'اختبار قصير يقيس ما تعرفه عن لائحة قواعد السلوك والمواظبة. ليس للدرجات، ونستخدمه لنعرف أي أجزاء تحتاج توضيحًا.', '[{"id":"grade","text":"الصف","type":"single","options":["الأول الثانوي","الثاني الثانوي","الثالث الثانوي"]}]'::jsonb, '[{"id":"attendance","name":"المواظبة والغياب","swot_axis":"internal","items":[{"text":"الغياب بعذر مقبول يُوثَّق بعذر رسمي يقدمه ولي الأمر خلال المدة المحددة في اللائحة.","reverse":false},{"text":"التأخر الصباحي المتكرر يترتب عليه إجراءات متدرجة في اللائحة.","reverse":false},{"text":"عدد أيام الغياب بدون عذر يؤثر في درجة السلوك والمواظبة.","reverse":false}],"if_low":[]},{"id":"conduct","name":"السلوك والاحترام","swot_axis":"internal","items":[{"text":"تحدد اللائحة مخالفات الدرجة الأولى والثانية وما يترتب على كل درجة.","reverse":false},{"text":"الإساءة اللفظية للزملاء أو المعلمين من المخالفات المنصوص عليها.","reverse":false},{"text":"التنمر بأشكاله من المخالفات التي لها إجراءات خاصة.","reverse":false}],"if_low":[]},{"id":"appearance","name":"الزي والمظهر","swot_axis":"internal","items":[{"text":"الزي المدرسي إلزامي ومحدد المواصفات في دليل الزي المدرسي.","reverse":false},{"text":"يُسمح بتغيير مواصفات الزي بحسب رغبة الطالب.","reverse":false}],"if_low":[]},{"id":"devices","name":"الأجهزة والهواتف","swot_axis":"internal","items":[{"text":"تحدد اللائحة ودليل استخدام الهواتف المحمولة متى يسمح بالجهاز المحمول وكيف يُتعامل معه عند المخالفة.","reverse":false},{"text":"تصوير الزملاء أو المعلمين دون إذن من المخالفات.","reverse":false}],"if_low":[]},{"id":"property","name":"الممتلكات والسلامة","swot_axis":"internal","items":[{"text":"إتلاف ممتلكات المدرسة يستوجب إصلاح الضرر بالإضافة إلى الإجراء التربوي.","reverse":false},{"text":"إحضار أدوات خطرة أو ممنوعة مخالفة جسيمة.","reverse":false}],"if_low":[]},{"id":"procedure","name":"الإجراءات وحقوق الطالب","swot_axis":"internal","items":[{"text":"للطالب حق سماع أقواله قبل اتخاذ الإجراء.","reverse":false},{"text":"لولي الأمر حق الاطلاع على المخالفات وإجراءات المدرسة.","reverse":false},{"text":"توجد وسيلة رسمية لتقديم تظلّم أو شكوى.","reverse":false}],"if_low":[]}]'::jsonb, '[{"id":"confidence","text":"ما مدى ثقتك بمعرفتك للائحة؟ (1–5)","type":"single","options":["1","2","3","4","5"]}]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['1-2-1-1','1-2-1-3','1-5-1-1','3-2-1-5','3-2-1-7']::text[], ARRAY['conduct']::text[], ARRAY['g_conduct','g_uniform','g_phones']::text[], 'pending') ON CONFLICT (slug) DO NOTHING;
INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('achievement_factors', 'العوامل المؤثرة في التحصيل الدراسي', 'student|parent', 'draft', '{"type":"likert5","labels":["لا أوافق بشدة","لا أوافق","محايد","أوافق","أوافق بشدة"]}'::jsonb, 'يساعدنا هذا الاستبيان في معرفة ما يدعم تحصيلك أو يعيقه لنقدّم دعمًا مناسبًا.', '[{"id":"grade","text":"الصف","type":"single","options":["الأول الثانوي","الثاني الثانوي","الثالث الثانوي"]},{"id":"self_level","text":"مستواي الدراسي الحالي (تقدير ذاتي)","type":"single","options":["ممتاز","جيد جدًا","جيد","مقبول","دون ذلك"]}]'::jsonb, '[{"id":"habits","name":"عادات الاستذكار","swot_axis":"internal","items":[{"text":"لدي جدول أسبوعي أذاكر وفقه.","reverse":false},{"text":"أراجع الدروس أولًا بأول لا قبل الاختبار فقط.","reverse":false},{"text":"أستخدم أساليب متنوعة في الاستذكار (ملخصات، أسئلة، شرح لزميل).","reverse":false},{"text":"أذاكر في مكان هادئ دون تشتت.","reverse":false}],"if_low":["ورشة عادات الاستذكار الفعال (تعزيز مهارات النجاح)"]},{"id":"time","name":"إدارة الوقت","swot_axis":"internal","items":[{"text":"أوازن بين الدراسة والأنشطة والراحة.","reverse":false},{"text":"أنهي واجباتي في وقتها.","reverse":false},{"text":"أضيّع وقتًا طويلًا في الجوال أو الألعاب أثناء الدراسة.","reverse":true}],"if_low":["تدريب على إدارة الوقت وحدّ الاستخدام الرقمي"]},{"id":"home","name":"الدعم الأسري والبيئة المنزلية","swot_axis":"external","items":[{"text":"يتابع أهلي مستواي الدراسي ويشجعونني.","reverse":false},{"text":"يتوفر لي مكان مناسب للدراسة في المنزل.","reverse":false},{"text":"أحصل على نوم كافٍ في أيام الدراسة.","reverse":false}],"if_low":["تواصل مع الأسرة وبرنامج للأسر (مجلس أولياء الأمور/لقاء فردي)"]},{"id":"school","name":"الدعم داخل المدرسة","swot_axis":"internal","items":[{"text":"يشرح معلمو مادتي بأساليب تساعدني على الفهم.","reverse":false},{"text":"أجد دعمًا إذا تأخرت في مادة ما (حصص علاج/تقوية).","reverse":false},{"text":"أشعر بالأمان في طرح أسئلتي بالفصل.","reverse":false}],"if_low":["رفع نتائج ضعف التدريس للجنة التحصيل الدراسي (دون تعميم على معلم محدد)"]},{"id":"barriers","name":"معوّقات التحصيل","swot_axis":"external","items":[{"text":"الغياب أو التأخر يفوّت علي دروسًا مهمة.","reverse":false},{"text":"أشعر بقلق شديد من الاختبارات.","reverse":false},{"text":"الدروس صعبة جدًا عليّ في مواد معينة.","reverse":false},{"text":"أحتاج إلى مساعدة في الدروس ولا أعرف من أطلبها منه.","reverse":false}],"if_low":["برنامج التهيئة الإرشادية للاختبارات","خطة علاجية للمتأخرين دراسيًا (سجل المتأخرين دراسيًا)"]}]'::jsonb, '[{"id":"top_barrier","text":"أكبر عائق يمنعني من تحسين مستواي:","type":"text"},{"id":"top_help","text":"أكثر ما يساعدني:","type":"text"}]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['1-2-1-1','1-2-1-3','2-1-1-9','3-2-1-2','3-2-1-5']::text[], ARRAY['motivation','absence_lag']::text[], ARRAY['p_motivation','p_success','g_interventions']::text[], NULL) ON CONFLICT (slug) DO NOTHING;